/* C ports of the three procedural dIFS formulas distributed with mb3d-rs.
 * Based on x86/handwritten.rs; original TGlad/Knighty attribution retained.
 * LGPL-2.1-or-later. No Rust code is linked. */
static double cf_sd_box(Vec p,Vec b){Vec d={fabs(p.x)-b.x,fabs(p.y)-b.y,fabs(p.z)-b.z},q={fmax(0,d.x),fmax(0,d.y),fmax(0,d.z)};return sqrt(dot(q,q))+fmin(0,fmax(d.x,fmax(d.y,d.z)));}
static double cf_pseudo_kleinian(Vec p,const double *v,double *trap){double scale=1,t=INFINITY;for(int i=0;i<(int)clamp(v[0],0,100);i++){Vec before=p;p=(Vec){2*clamp(p.x,-v[3],v[3])-p.x,2*clamp(p.y,-v[4],v[4])-p.y,2*clamp(p.z,-v[5],v[5])-p.z};double r=dot(p,p);t=fmin(t,r);double k=fmax(1,v[2]/fmax(1e-300,r));p=add(mul(p,k),(Vec){v[6],v[7],v[8]});scale*=k;if(p.x==before.x&&p.y==before.y&&p.z==before.z)break;}
    Vec q={p.x-v[11],p.y-v[12],p.z-v[13]};double d;if((int)v[1]==1){d=(fabs(hypot(q.x,q.y)*q.z)-v[9])/sqrt(dot(q,q)+fabs(v[9]));}else if((int)v[1]==2)d=fabs(cf_sd_box(q,(Vec){1,1,1})-v[9]);else d=fabs(q.z);*trap=sqrt(t)*v[14];return fabs(.5*d/scale-v[10]);}
static double cf_sphere_tree(Vec p,const double *v,double *trap){double k=v[0],root3=sqrt(3),scale=1,scl=v[2]!=0?root3:1,inner=k*scl/(k*k+scl),innerB=inner*inner*.25,shift=(k*k+scl)/(k*(1+scl)),mid=.25*(k+1),buffer=.6*k,col=0,cw=1;Vec t1={root3/2,-.5,0},t2={-root3/2,-.5,0};int levels=(int)fmax(0,v[1]);
    for(int i=0;i<levels;i++){if(render_cancelled())break;Vec pb=add(p,(Vec){0,0,-inner*.5});if(dot(pb,pb)<innerB)break;double maxH=i==0?-100:.4;Vec pc=add(p,(Vec){0,0,-buffer});if(p.z>maxH&&dot(pc,pc)>buffer*buffer)break;
        Vec p2=add(p,(Vec){0,0,-k*.5});if(dot(p2,p2)<k*k*.25){p.z-=k;double s2=k*(k-inner),mag=dot(p,p);p=mul(p,s2/mag);scale*=mag/s2;p.z=-p.z-(k-inner);double sh=.1*(p.x*p.x+p.y*p.y);p.z+=sh;if(p.z>0)p.z-=inner*floor(p.z/inner);p.z-=sh;p.z+=k-inner;p.z=-p.z;mag=dot(p,p);p=mul(p,s2/mag);scale*=mag/s2;p.z+=k;}
        Vec pd=add(p,(Vec){0,0,-mid});double sc=dot(p,p);if(p.z<maxH&&dot(pd,pd)>mid*mid){scale*=sc;p=mul(p,1/sc);}else{scale*=sc;p=mul(p,1/sc);p.z=-(p.z-shift);p=mul(p,scl);scale/=scl;p.z+=shift;if(v[2]!=0){double x=p.x,y=p.y;p.x=x*cos(PI/6)+y*sin(PI/6);p.y=-x*sin(PI/6)+y*cos(PI/6);}}
        double h=p.z,x0=(.5*p.x-root3*.5*p.y)*2/root3,y0=(.5*p.x+root3*.5*p.y)*2/root3,cx=floor(x0),cy=floor(y0),x=x0-cx,y=y0-cy,flip=0;if(x+y>1){x=1-x;y=1-y;flip=1;}double hv=cx*.6180339887+cy*.4142135624+flip*.5;col+=cw*(hv-floor(hv));cw*=.35;p=(Vec){x*t1.x-y*t2.x,x*t1.y-y*t2.y,0};Vec d1=add(p,mul(t1,-1)),d2=add(p,t2);double l0=dot(p,p),l1=dot(d1,d1),l2=dot(d2,d2);if(l1<l0&&l1<l2)p=add(p,mul(t1,-(2*dot(t1,p)-1)));else if(l2<l0&&l2<l1)p=add(p,mul(t2,-(2*dot(p,t2)+1)));p.z=h;
    }Vec q=add(p,(Vec){0,0,-.5*k});*trap=col*v[3];return (sqrt(dot(q,q))-.5*k)*scale;}
static uint64_t cf_ulam_number(int64_t x,int64_t y){int64_t k=llabs(x)>llabs(y)?llabs(x):llabs(y);if(!k)return 1;int64_t m=(2*k-1)*(2*k-1);return x==k&&y>-k?m+y+k:y==k?m+3*k-x:x==-k?m+5*k-y:m+7*k+x;}
static uint64_t cf_ulam_number3(int64_t x,int64_t y,int64_t z){int64_t k=llabs(x);if(llabs(y)>k)k=llabs(y);if(llabs(z)>k)k=llabs(z);if(!k)return 1;uint64_t b=2*k-1,face=(2*k+1)*(2*k+1),ring=8*k,u=cf_ulam_number(x,y)-1,off=z==-k?u:z==k?face+(2*k-1)*ring+u:face+(z+k-1)*ring+(u-b*b);return b*b*b+off+1;}
static unsigned cf_divisor_count(uint64_t n){unsigned c=0;for(uint64_t i=1;i*i<=n;i++)if(n%i==0)c+=i*i==n?1:2;return c;}
static double cf_ulam_spiral(Vec p,const double *v,double *trap){int mode=(int)v[0];double r=clamp(v[1],0,mode==3?120:2000),hs=.5*(1-clamp(v[3],0,.95));Vec c={floor(p.x+.5),floor(p.y+.5),floor(p.z+.5)},l=add(p,mul(c,-1)),s={l.x<0?-1:1,l.y<0?-1:1,l.z<0?-1:1};double lateral=fmax(fabs(p.x)-(r+.5),fabs(p.y)-(r+.5)),best=.5,col=0;
    if(mode==3){double out=fmax(lateral,fabs(p.z)-(r+.5));if(out>.5){*trap=0;return out;}for(int i=0;i<8;i++){Vec o={(i&1)*s.x,((i>>1)&1)*s.y,((i>>2)&1)*s.z},q=add(c,o);if(fabs(q.x)>r||fabs(q.y)>r||fabs(q.z)>r)continue;unsigned dc=cf_divisor_count(cf_ulam_number3(q.x,q.y,q.z));if(dc==2){double d=cf_sd_box(add(l,mul(o,-1)),(Vec){hs,hs,hs});if(d<best){best=d;col=log(dc);}}}*trap=col*v[4];return fmax(best,out);}
    if(lateral>.5){*trap=0;return lateral;}double top=mode==1?.05+v[2]*.5*log2(2*r+1):mode==2?2*hs:fmax(v[2],.05);if(p.z-top>.5){*trap=0;return p.z-top;}
    for(int i=0;i<4;i++){double ox=(i&1)*s.x,oy=((i>>1)&1)*s.y,qx=c.x+ox,qy=c.y+oy;if(fabs(qx)>r||fabs(qy)>r)continue;unsigned dc=cf_divisor_count(cf_ulam_number(qx,qy));double x=l.x-ox,y=l.y-oy,d;if(mode==2){double rad=hs*fmin(sqrt(dc)/6,1);d=sqrt(x*x+y*y+(p.z-rad)*(p.z-rad))-rad;}else{double h=mode==1?.05+v[2]*.5*log2(fmax(2,dc)/2.):dc==2?v[2]:.05;d=cf_sd_box((Vec){x,y,p.z-h*.5},(Vec){hs,hs,h*.5});}if(d<best){best=d;col=log(dc);}}
    *trap=col*v[4];return fmax(best,lateral);}
static int cf_procedural(Vec point,unsigned kind,const double values[16],double *distance,double *trap){switch(kind){case 1:*distance=cf_pseudo_kleinian(point,values,trap);return 1;case 2:*distance=cf_sphere_tree(point,values,trap);return 1;case 3:*distance=cf_ulam_spiral(point,values,trap);return 1;default:return 0;}}
